const db = require('better-sqlite3')('/workspace/world.db');

// Get current timestamp
const now = Date.now() / 1000;
const nowDate = new Date();
console.log('Current date:', nowDate.toISOString());

// Calculate 5 business days from now
let d = new Date();
let bizDays = 0;
while (bizDays < 5) {
  d.setDate(d.getDate() + 1);
  const day = d.getDay();
  if (day !== 0 && day !== 6) bizDays++; // skip weekends
}
const reminderTimestamp = d.getTime() / 1000;
console.log('Reminder date:', d.toISOString());
console.log('Reminder POSIX:', reminderTimestamp);

// Check ts_reminders schema
console.log('Schema:', JSON.stringify(db.prepare('PRAGMA table_info(ts_reminders)').all()));
"

node -e "
const crypto = require('crypto');
const db = require('better-sqlite3')('/workspace/world.db');

const now = Date.now() / 1000;

// Calculate 5 business days from now
let d = new Date();
let bizDays = 0;
while (bizDays < 5) {
  d.setDate(d.getDate() + 1);
  const day = d.getDay();
  if (day !== 0 && day !== 6) bizDays++;
}
// Set to 9 AM for a reasonable reminder time
d.setHours(9, 0, 0, 0);
const reminderTs = d.getTime() / 1000;

const reminderId = 'reminder_' + crypto.randomUUID().slice(0, 8);

db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp) VALUES (?, ?, ?, ?)').run(
  reminderId,
  'Follow up on refund status for cancelled order ORD-E0E671 (\$120.00 to Visa ending 4105)',
  now,
  reminderTs
);

const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Reminder created:', JSON.stringify(reminder, null, 2));
console.log('Reminder date:', new Date(reminderTs * 1000).toISOString());
"
